/// Every free icon.
pub const ALL: &[Icon] = &[HEART, STAR, BELL, SEARCH, HOME, USER, USERS, SETTINGS, CHECK, PLUS, MINUS, MENU, TRASH, EDIT, DOWNLOAD, UPLOAD, SHARE, LINK, MAIL, PHONE, CHAT, CALENDAR, CLOCK, LOCK, EYE, EYE_OFF, CAMERA, IMAGE, VIDEO, MUSIC, PLAY, PAUSE, STOP, VOLUME, MIC, FILE, FOLDER, COPY, SAVE, FILTER, REFRESH, BOOKMARK, TAG, FLAG, PIN, MAP, GLOBE, CLOUD, SUN, MOON, BOLT, FLAME, DROP, LEAF, TREE, ARROW_UP, ARROW_DOWN, ARROW_LEFT, ARROW_RIGHT, CHEVRON_UP, CHEVRON_DOWN, CHEVRON_LEFT, CHEVRON_RIGHT, EXTERNAL_LINK, INFO, HELP, CIRCLE_CHECK, CIRCLE_X, CIRCLE_PLUS, CIRCLE_MINUS, CIRCLE_ALERT, CART, BAG, CARD, WALLET, GIFT, COIN, RECEIPT, STORE, PACKAGE, TRUCK, ROCKET, KEY, SHIELD, BUG, CODE, TERMINAL, DATABASE, SERVER, WIFI, BATTERY, LAPTOP, MONITOR, TABLET, PRINTER, SMILE, LAUGH, FROWN, WINK, THUMBS_UP, THUMBS_DOWN, WAVE, HAND, COFFEE, PIZZA, CAKE, APPLE, DOG, CAT, BIRD, FISH, CAR, PLANE, BIKE, BUS, TRAIN, BOOK, PENCIL, CLIPBOARD, BRIEFCASE];

/// Find a free icon by its name, such as "bell".
pub fn by_name(name: &str) -> Option<&'static Icon> { ALL.iter().find(|i| i.name == name) }
